#include <stdlib.h>
#include <stdio.h>
#include <errno.h>
#include <stddef.h>
#define _cleanup_(x)
struct dbhandle {void *db;};
struct {unsigned int cpu_threads,io_threads;int fdupes_mode;char *hashfile;} options={0};
struct {unsigned int dedupe_seq;} dbfile_cfg;
unsigned int dedupe_seq;int quiet,debug,list_only_opt,rm_only_opt;enum {H_READ,H_WRITE,H_UPDATE};int use_hashfile=H_UPDATE;
#define init_filerec(...) 0
#define get_num_cpus(...) 0
#define parse_options(...) 0
#define increase_limits(...) 0
#define process_fdupes(...) 0
#define list_db_files(...) 0
#define rm_db_files(...) 0
#define dbfile_open_handle(...) ((struct dbhandle*)0)
#define dbfile_set_gdb(...) 0
#define dbfile_get_config(...) 0
#define print_header(...) 0
#define dbfile_prune_unscanned_files(...) 0
#define eprintf(...) 0
#define scan_files(...) 0
#define qprintf(...) 0
#define process_duplicates(...) 0
#define free_all_filerecs(...) 0
#define print_mem_stats(...) 0
int main(int argc, char **argv)
{
	int ret, filelist_idx = 0;
	_cleanup_(sqlite3_close_cleanup) struct dbhandle *db = NULL;

	char stdbuf[BUFSIZ];
	setvbuf(stdout, stdbuf, _IOLBF, BUFSIZ);

	init_filerec();

	/* Set the default CPU limits before parsing the user options */
	get_num_cpus(&(options.cpu_threads), &(options.io_threads));

	ret = parse_options(argc, argv, &filelist_idx);
	if (ret) {
		exit(1);
	}

	/* Allow larger than unusal amount of open files. On linux
	 * this should bw increase form 1K to 512K open files
	 * simultaneously.
	 *
	 * On multicore SSD machines it's not hard to get to 1K open
	 * files.
	 */
	increase_limits();

	if (options.fdupes_mode)
		return process_fdupes();

	if (list_only_opt)
		return list_db_files(options.hashfile);
	else if (rm_only_opt)
		return rm_db_files(argc - filelist_idx, &argv[filelist_idx]);

	db = dbfile_open_handle(options.hashfile);
	if (!db)
		goto out;

	dbfile_set_gdb(db);

	ret = dbfile_get_config(db->db, &dbfile_cfg);
	if (ret)
		goto out;

	dedupe_seq = dbfile_cfg.dedupe_seq;

	print_header();

	if (use_hashfile == H_WRITE || use_hashfile == H_UPDATE) {
		ret = dbfile_prune_unscanned_files(db);
		if (ret) {
			eprintf("Unable to prune unscanned files\n");
			goto out;
		}

		ret = scan_files(argc, argv, filelist_idx, db);
		if (ret)
			goto out;

		qprintf("Hashfile \"%s\" written\n",
			options.hashfile);
	}

	if (use_hashfile == H_READ || use_hashfile == H_UPDATE)
		process_duplicates(db);

out:
	free_all_filerecs();

#ifdef DEBUG_BUILD
	print_mem_stats();
#else
	if (ret == ENOMEM || debug)
		print_mem_stats();
#endif

	return ret;
}
